function createBaseHealthResponse(): HealthResponse {
  return { status: "", service: "", version: "" };
}

export const HealthResponse: MessageFns<HealthResponse> = {
  encode(message: HealthResponse, writer: BinaryWriter = new BinaryWriter()): BinaryWriter {
    if (message.status !== "") {
      writer.uint32(10).string(message.status);
    }
    if (message.service !== "") {
      writer.uint32(18).string(message.service);
    }
    if (message.version !== "") {
      writer.uint32(26).string(message.version);
    }
    return writer;
  },

  decode(input: BinaryReader | Uint8Array, length?: number): HealthResponse {
    const reader = input instanceof BinaryReader ? input : new BinaryReader(input);
    const previousRecursionDepth = (reader as any).__tsProtoDecodeDepth ?? 0;
    if (previousRecursionDepth >= 100) {
      throw new globalThis.Error("protobuf decode recursion limit exceeded");
    }
    (reader as any).__tsProtoDecodeDepth = previousRecursionDepth + 1;
    try {
      const end = length === undefined ? reader.len : reader.pos + length;
      const message = createBaseHealthResponse();
      while (reader.pos < end) {
        const tag = reader.uint32();
        switch (tag >>> 3) {
          case 1: {
            if (tag !== 10) {
              break;
            }

            message.status = reader.string();
            continue;
          }
          case 2: {
            if (tag !== 18) {
              break;
            }

            message.service = reader.string();
            continue;
          }
          case 3: {
            if (tag !== 26) {
              break;
            }

            message.version = reader.string();
            continue;
          }
        }
        if ((tag & 7) === 4 || tag === 0) {
          break;
        }
        reader.skip(tag & 7);
      }
      return message;
    } finally {
      (reader as any).__tsProtoDecodeDepth = previousRecursionDepth;
    }
  },

  fromJSON(object: any): HealthResponse {
    return {
      status: isSet(object.status) ? globalThis.String(object.status) : "",
      service: isSet(object.service) ? globalThis.String(object.service) : "",
      version: isSet(object.version) ? globalThis.String(object.version) : "",
    };
  },

  toJSON(message: HealthResponse): unknown {
    const obj: any = {};
    if (message.status !== "") {
      obj.status = message.status;
    }
    if (message.service !== "") {
      obj.service = message.service;
    }
    if (message.version !== "") {
      obj.version = message.version;
    }
    return obj;
  },

  create(base?: DeepPartial<HealthResponse>): HealthResponse {
    return HealthResponse.fromPartial(base ?? {});
  },
  fromPartial(object: DeepPartial<HealthResponse>): HealthResponse {
    const message = createBaseHealthResponse();
    message.status = object.status ?? "";
    message.service = object.service ?? "";
    message.version = object.version ?? "";
    return message;
  },
};

/**
 * The service boundary between the Next.js BFF and the Python extractor.
 *
 * Extraction takes 10-40 seconds, so Extract does NOT return a recipe: it
 * enqueues and hands back a job id immediately. The caller then watches
 * StreamStatus, which pushes each stage transition as it happens rather than
 * making the client poll.
 *
 * This mirrors packages/schema/src/job.ts and apps/extractor/app/schema.py.
 * Phase 4's whole point is that these three stop being hand-maintained
 * mirrors: the generated stubs become the source of truth, and the drift test
 * against packages/schema/fixtures/ is what proves the transition is clean.
 */
export type ExtractorDefinition = typeof ExtractorDefinition;
export const ExtractorDefinition = {
  name: "Extractor",
  fullName: "mise.extractor.v1.Extractor",
  methods: {
    /**
     * Enqueue a video. Idempotent by video_id: submitting one already queued or
     * running returns the existing job rather than racing a second worker onto
     * the same video.
     */
    extract: {
      name: "Extract",
      requestType: ExtractRequest as typeof ExtractRequest,
      requestStream: false,
      responseType: ExtractResponse as typeof ExtractResponse,
      responseStream: false,
      options: {},
    },
    /**
     * Server-streaming job status. Emits on every state or stage change and
     * completes when the job reaches a terminal state, so the caller never
     * polls and never has to guess when to stop listening.
     */
    streamStatus: {
      name: "StreamStatus",
      requestType: StreamStatusRequest as typeof StreamStatusRequest,
      requestStream: false,
      responseType: Job as typeof Job,
      responseStream: true,
      options: {},
    },
    /**
     * One-shot status, for a caller that reconnected and only needs where
     * things stand.
     */
    getStatus: {
      name: "GetStatus",
      requestType: GetStatusRequest as typeof GetStatusRequest,
      requestStream: false,
      responseType: Job as typeof Job,
      responseStream: false,
      options: {},
    },
    /**
     * Fetch an already-extracted recipe by VIDEO id.
     *
     * Distinct from GetStatus, which is keyed by job id: a recipe outlives the
     * job that produced it, and recipe pages are addressed by the video so the
     * URL is stable and shareable. Reads the cache and never enqueues.
     */
    getRecipe: {
      name: "GetRecipe",
      requestType: GetRecipeRequest as typeof GetRecipeRequest,
      requestStream: false,
      responseType: GetRecipeResponse as typeof GetRecipeResponse,
      responseStream: false,
      options: {},
    },
    /**
     * Liveness only — deliberately says nothing about downstream health, so an
     * orchestrator cannot restart a healthy service because Redis is slow.
     */
    health: {
      name: "Health",
      requestType: HealthRequest as typeof HealthRequest,
      requestStream: false,
      responseType: HealthResponse as typeof HealthResponse,
      responseStream: false,
      options: {},
    },
  },
} as const;

type Builtin = Date | Function | Uint8Array | string | number | boolean | undefined;

export type DeepPartial<T> = T extends Builtin ? T
  : T extends globalThis.Array<infer U> ? globalThis.Array<DeepPartial<U>>
  : T extends ReadonlyArray<infer U> ? ReadonlyArray<DeepPartial<U>>
  : T extends {} ? { [K in keyof T]?: DeepPartial<T[K]> }
  : Partial<T>;

function isSet(value: any): boolean {
  return value !== null && value !== undefined;
}

export interface MessageFns<T> {
  encode(message: T, writer?: BinaryWriter): BinaryWriter;
  decode(input: BinaryReader | Uint8Array, length?: number): T;
  fromJSON(object: any): T;
  toJSON(message: T): unknown;
  create(base?: DeepPartial<T>): T;
  fromPartial(object: DeepPartial<T>): T;
}
